function calculatePrice(product: any) {
  switch (product.type) {
    case 'book':
      return product.basePrice * 0.9;
    case 'digital':
      return product.basePrice;
    case 'subscription':
      return product.basePrice * product.duration;
    default:
      throw new Error('Unknown product type');
  }
}

function chargeCustomer(method: string, data: any) {
  switch (method) {
    case 'card': return chargeCard(data);
    case 'paypal': return chargePaypal(data);
    case 'bank': return chargeBank(data);
  }
}

function refundCustomer(method: string, data: any) {
  switch (method) {
    case 'card': return refundCard(data);
    case 'paypal': return refundPaypal(data);
    case 'bank': return refundBank(data);
  }
}

